        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        r = (props.get(el) or {}).get('covalent_radius_A')
        if r is None or r <= 0:
            continue
        total += x * r ** 3
        amount += x
    return float(4.1887902047863905 * total / (amount * v)) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        compression = max(0.0, 1.0 - d / (radii[i] + radii[j]))
        total += occ[i] * occ[j] * compression * compression
    return float(total / amount)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    first = 0.0
    second = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0 or radii[i] <= 0:
            continue
        coordination = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or radii[j] <= 0:
                continue
            coordination += occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        first += occ[i] * coordination
        second += occ[i] * coordination * coordination
        amount += occ[i]
    if amount <= 0 or first <= 0:
        return 0.0
    mean = first / amount
    variance = max(0.0, second / amount - mean * mean)
    return float(variance ** 0.5 / mean)

def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        valence = (props.get(el) or {}).get('valence_electrons')
        if valence is None or valence < 0:
            continue
        total += x * valence
        amount += x
    return float(total / (amount * v)) if amount > 0 else 0.0
